-- Revert sig:closed_vocabulary from pg
-- Restores the pre-change reason CHECK and drops the genre table. Registered
-- vocabulary rows are deleted only where no live row references them — rows
-- claims already resolve through are recorded registry history (append-only,
-- P1-P3) and stay.

BEGIN;

ALTER TABLE assertion_quarantine DROP CONSTRAINT assertion_quarantine_reason_check;
ALTER TABLE assertion_quarantine ADD CONSTRAINT assertion_quarantine_reason_check
  CHECK (reason IN ('bad_digest','unknown_predicate','unknown_object_type',
                    'unknown_value_kind','missing_capture_binding',
                    'unsupported_locator','extractor_failure',
                    'version_mismatch','missing_required_field',
                    'unknown_qualifier'));

DELETE FROM directness_matrix WHERE ruleset_version = '1.0.0';

DELETE FROM vocab_predicate
 WHERE predicate_id IN ('accountability_event', 'acquisition_channel', 'acquisition_cost', 'acquisition_method', 'active_device_count', 'actually_provides_capability', 'affected_party_class', 'agency_county', 'agency_latitude', 'agency_longitude', 'agency_name', 'agency_ori9', 'agency_registry_entry', 'agency_state', 'agency_type', 'agenda_item', 'ai_surveillance_supplier', 'ai_surveillance_tech_from_china', 'ai_surveillance_tech_from_us', 'amends_contract', 'amount', 'approval_status', 'as_of', 'asset_data_controller', 'asset_exists_at_location', 'asset_operator', 'asset_type', 'atlas_category_retired', 'audit_case_code_required', 'audit_cell_redacted', 'audit_mechanism', 'authorization_state', 'authorizes', 'award_date', 'bill_chamber', 'bill_external_id', 'bill_identifier', 'bill_jurisdiction', 'bill_matched_keyword', 'bill_session', 'bill_status', 'bill_status_date', 'bill_title', 'brand', 'brand_qid', 'buyer', 'camera_coordinate_source', 'camera_county', 'camera_direction', 'camera_external_ref', 'camera_jurisdiction', 'camera_latitude', 'camera_longitude', 'camera_mount', 'camera_name', 'camera_operator', 'camera_registry_publisher', 'camera_roadway', 'camera_status', 'camera_type', 'candidate_location_estimate', 'candidate_promotion_status', 'citation', 'claimed_device_count', 'complaint_count', 'conditions', 'configured_access_edge', 'configured_retention_days', 'configured_sharing_partner', 'configured_sharing_partner_set', 'constrains_capability', 'constrains_technology', 'content_term', 'contract', 'contract_amount', 'contract_end_date', 'contract_number', 'contract_signed_date', 'contract_start_date', 'contract_term_end', 'contract_value', 'contracted_device_count', 'count_scope', 'count_scope_detail', 'country', 'currency', 'data_access', 'data_system_retention', 'data_system_scope', 'deployed', 'deployment_ended', 'deployment_exists', 'deployment_lifecycle_transition', 'deployment_location', 'deprecation_reason', 'description', 'direction', 'disclosure